mapper.select:
select



 order by f.reported_at desc, f.fault_id desc
 limit #{limit}
 offset #{offset}

select status
  from fault_report
 where fault_id = #{faultId}

mapper.insert:
insert into fault_history (
      fault_id
    , employee_id
    , before_status
    , after_status
    , action_type
    , memo
    , created_at
) values (
      #{faultId}
    , #{employeeId}
    , #{beforeStatus}
    , #{afterStatus}
    , #{actionType}
    , #{memo}
    , current_timestamp
)
